CREATE OR REPLACE TABLE local_duck.fs_clima AS 

SELECT 
    --CAST(voo.data_hora_clima AS TIMESTAMP) AS ts_data_hora_clima,
    --CAST(clima.data_hora_clima AS TIMESTAMP) AS ts_data_hora_voo,
    voo.idVoo,
    voo.partidaPrevista,
    AVG(CAST(clima.precipitacaoTotal AS REAL)) as avgPrecipitacaoTotal24h,
    AVG(CAST(clima.pressaoAtmosferica AS REAL)) as avgPressaoAtmosferica24h,
    AVG(CAST(clima.pressaoAtmosfericaMaxUltimaHora AS REAL)) as avgPressaoAtmosfericaMaxUltimaHora24h,
    AVG(CAST(clima.pressaoAtmosfericaMinUltimaHora AS REAL)) as avgPressaoAtmosfericaMinUltimaHora24h,
    AVG(CAST(clima.temperaturaBulboSeco AS REAL)) as avgTemperaturaBulboSeco24h,
    AVG(CAST(clima.temperaturaPontoOrvalho AS REAL)) as avgTemperaturaPontoOrvalho24h,
    AVG(CAST(clima.temperaturaMaxUltimaHora AS REAL)) as avgTemperaturaMaxUltimaHora24h,
    AVG(CAST(clima.temperaturaMinUltimaHora AS REAL)) as avgTemperaturaMinUltimaHora24h,
    AVG(CAST(clima.temperaturaPontoOrvalhoMaxUltimaHora AS REAL)) as avgTemperaturaPontoOrvalhoMaxUltimaHora24h,
    AVG(CAST(clima.temperaturaPontoOrvalhoMinUltimaHora AS REAL)) as avgTemperaturaPontoOrvalhoMinUltimaHora24h,
    AVG(CAST(clima.umidadeRelativaMaxUltimaHora AS REAL)) as avgUmidadeRelativaMaxUltimaHora24h,
    AVG(CAST(clima.umidadeRelativaMinUltimaHora AS REAL)) as avgUmidadeRelativaMinUltimaHora24h,
    AVG(CAST(clima.umidadeRelativa AS REAL)) as avgUmidadeRelativa24h,
    AVG(CAST(clima.ventoDirecaoGraus AS REAL)) as avgVentoDirecaoGraus24h,
    AVG(CAST(clima.ventoRajadaMax AS REAL)) as avgVentoRajadaMax24h,
    AVG(CAST(clima.ventoVelocidade AS REAL)) as avgVentoVelocidade24h,

    AVG(CAST(clima.precipitacaoTotal AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgPrecipitacaoTotal12h,
    AVG(CAST(clima.pressaoAtmosferica AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgPressaoAtmosferica12h,
    AVG(CAST(clima.pressaoAtmosfericaMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgPressaoAtmosfericaMaxUltimaHora12h,
    AVG(CAST(clima.pressaoAtmosfericaMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgPressaoAtmosfericaMinUltimaHora12h,
    AVG(CAST(clima.temperaturaBulboSeco AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgTemperaturaBulboSeco12h,
    AVG(CAST(clima.temperaturaPontoOrvalho AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgTemperaturaPontoOrvalho12h,
    AVG(CAST(clima.temperaturaMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgTemperaturaMaxUltimaHora12h,
    AVG(CAST(clima.temperaturaMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgTemperaturaMinUltimaHora12h,
    AVG(CAST(clima.temperaturaPontoOrvalhoMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgTemperaturaPontoOrvalhoMaxUltimaHora12h,
    AVG(CAST(clima.temperaturaPontoOrvalhoMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgTemperaturaPontoOrvalhoMinUltimaHora12h,
    AVG(CAST(clima.umidadeRelativaMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgUmidadeRelativaMaxUltimaHora12h,
    AVG(CAST(clima.umidadeRelativaMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgUmidadeRelativaMinUltimaHora12h,
    AVG(CAST(clima.umidadeRelativa AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgUmidadeRelativa12h,
    AVG(CAST(clima.ventoDirecaoGraus AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgVentoDirecaoGraus12h,
    AVG(CAST(clima.ventoRajadaMax AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgVentoRajadaMax12h,
    AVG(CAST(clima.ventoVelocidade AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS avgVentoVelocidade12h,

    AVG(CAST(clima.precipitacaoTotal AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgPrecipitacaoTotal3h,
    AVG(CAST(clima.pressaoAtmosferica AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgPressaoAtmosferica3h,
    AVG(CAST(clima.pressaoAtmosfericaMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgPressaoAtmosfericaMaxUltimaHora3h,
    AVG(CAST(clima.pressaoAtmosfericaMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgPressaoAtmosfericaMinUltimaHora3h,
    AVG(CAST(clima.temperaturaBulboSeco AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgTemperaturaBulboSeco3h,
    AVG(CAST(clima.temperaturaPontoOrvalho AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgTemperaturaPontoOrvalho3h,
    AVG(CAST(clima.temperaturaMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgTemperaturaMaxUltimaHora3h,
    AVG(CAST(clima.temperaturaMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgTemperaturaMinUltimaHora3h,
    AVG(CAST(clima.temperaturaPontoOrvalhoMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgTemperaturaPontoOrvalhoMaxUltimaHora3h,
    AVG(CAST(clima.temperaturaPontoOrvalhoMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgTemperaturaPontoOrvalhoMinUltimaHora3h,
    AVG(CAST(clima.umidadeRelativaMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgUmidadeRelativaMaxUltimaHora3h,
    AVG(CAST(clima.umidadeRelativaMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgUmidadeRelativaMinUltimaHora3h,
    AVG(CAST(clima.umidadeRelativa AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgUmidadeRelativa3h,
    AVG(CAST(clima.ventoDirecaoGraus AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgVentoDirecaoGraus3h,
    AVG(CAST(clima.ventoRajadaMax AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgVentoRajadaMax3h,
    AVG(CAST(clima.ventoVelocidade AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS avgVentoVelocidade3h,

    MAX(CAST(clima.precipitacaoTotal AS REAL)) as maxPrecipitacaoTotal24h,
    MAX(CAST(clima.pressaoAtmosferica AS REAL)) as maxPressaoAtmosferica24h,
    MAX(CAST(clima.pressaoAtmosfericaMaxUltimaHora AS REAL)) as maxPressaoAtmosfericaMaxUltimaHora24h,
    MAX(CAST(clima.pressaoAtmosfericaMinUltimaHora AS REAL)) as maxPressaoAtmosfericaMinUltimaHora24h,
    MAX(CAST(clima.temperaturaBulboSeco AS REAL)) as maxTemperaturaBulboSeco24h,
    MAX(CAST(clima.temperaturaPontoOrvalho AS REAL)) as maxTemperaturaPontoOrvalho24h,
    MAX(CAST(clima.temperaturaMaxUltimaHora AS REAL)) as maxTemperaturaMaxUltimaHora24h,
    MAX(CAST(clima.temperaturaMinUltimaHora AS REAL)) as maxTemperaturaMinUltimaHora24h,
    MAX(CAST(clima.temperaturaPontoOrvalhoMaxUltimaHora AS REAL)) as maxTemperaturaPontoOrvalhoMaxUltimaHora24h,
    MAX(CAST(clima.temperaturaPontoOrvalhoMinUltimaHora AS REAL)) as maxTemperaturaPontoOrvalhoMinUltimaHora24h,
    MAX(CAST(clima.umidadeRelativaMaxUltimaHora AS REAL)) as maxUmidadeRelativaMaxUltimaHora24h,
    MAX(CAST(clima.umidadeRelativaMinUltimaHora AS REAL)) as maxUmidadeRelativaMinUltimaHora24h,
    MAX(CAST(clima.umidadeRelativa AS REAL)) as maxUmidadeRelativa24h,
    MAX(CAST(clima.ventoDirecaoGraus AS REAL)) as maxVentoDirecaoGraus24h,
    MAX(CAST(clima.ventoRajadaMax AS REAL)) as maxVentoRajadaMax24h,
    MAX(CAST(clima.ventoVelocidade AS REAL)) as maxVentoVelocidade24h,

    MAX(CAST(clima.precipitacaoTotal AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxPrecipitacaoTotal12h,
    MAX(CAST(clima.pressaoAtmosferica AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxPressaoAtmosferica12h,
    MAX(CAST(clima.pressaoAtmosfericaMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxPressaoAtmosfericaMaxUltimaHora12h,
    MAX(CAST(clima.pressaoAtmosfericaMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxPressaoAtmosfericaMinUltimaHora12h,
    MAX(CAST(clima.temperaturaBulboSeco AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxTemperaturaBulboSeco12h,
    MAX(CAST(clima.temperaturaPontoOrvalho AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxTemperaturaPontoOrvalho12h,
    MAX(CAST(clima.temperaturaMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxTemperaturaMaxUltimaHora12h,
    MAX(CAST(clima.temperaturaMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxTemperaturaMinUltimaHora12h,
    MAX(CAST(clima.temperaturaPontoOrvalhoMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxTemperaturaPontoOrvalhoMaxUltimaHora12h,
    MAX(CAST(clima.temperaturaPontoOrvalhoMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxTemperaturaPontoOrvalhoMinUltimaHora12h,
    MAX(CAST(clima.umidadeRelativaMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxUmidadeRelativaMaxUltimaHora12h,
    MAX(CAST(clima.umidadeRelativaMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxUmidadeRelativaMinUltimaHora12h,
    MAX(CAST(clima.umidadeRelativa AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxUmidadeRelativa12h,
    MAX(CAST(clima.ventoDirecaoGraus AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxVentoDirecaoGraus12h,
    MAX(CAST(clima.ventoRajadaMax AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxVentoRajadaMax12h,
    MAX(CAST(clima.ventoVelocidade AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 13 HOUR)) AS maxVentoVelocidade12h,

    MAX(CAST(clima.precipitacaoTotal AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxPrecipitacaoTotal3h,
    MAX(CAST(clima.pressaoAtmosferica AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxPressaoAtmosferica3h,
    MAX(CAST(clima.pressaoAtmosfericaMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxPressaoAtmosfericaMaxUltimaHora3h,
    MAX(CAST(clima.pressaoAtmosfericaMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxPressaoAtmosfericaMinUltimaHora3h,
    MAX(CAST(clima.temperaturaBulboSeco AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxTemperaturaBulboSeco3h,
    MAX(CAST(clima.temperaturaPontoOrvalho AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxTemperaturaPontoOrvalho3h,
    MAX(CAST(clima.temperaturaMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxTemperaturaMaxUltimaHora3h,
    MAX(CAST(clima.temperaturaMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxTemperaturaMinUltimaHora3h,
    MAX(CAST(clima.temperaturaPontoOrvalhoMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxTemperaturaPontoOrvalhoMaxUltimaHora3h,
    MAX(CAST(clima.temperaturaPontoOrvalhoMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxTemperaturaPontoOrvalhoMinUltimaHora3h,
    MAX(CAST(clima.umidadeRelativaMaxUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxUmidadeRelativaMaxUltimaHora3h,
    MAX(CAST(clima.umidadeRelativaMinUltimaHora AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxUmidadeRelativaMinUltimaHora3h,
    MAX(CAST(clima.umidadeRelativa AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxUmidadeRelativa3h,
    MAX(CAST(clima.ventoDirecaoGraus AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxVentoDirecaoGraus3h,
    MAX(CAST(clima.ventoRajadaMax AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxVentoRajadaMax3h,
    MAX(CAST(clima.ventoVelocidade AS REAL)) FILTER (WHERE CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 4 HOUR)) AS maxVentoVelocidade3h,

    STDDEV(CAST(clima.precipitacaoTotal AS REAL)) as stddevPrecipitacaoTotal24h,
    STDDEV(CAST(clima.pressaoAtmosferica AS REAL)) as stddevPressaoAtmosferica24h,
    STDDEV(CAST(clima.pressaoAtmosfericaMaxUltimaHora AS REAL)) as stddevPressaoAtmosfericaMaxUltimaHora24h,
    STDDEV(CAST(clima.pressaoAtmosfericaMinUltimaHora AS REAL)) as stddevPressaoAtmosfericaMinUltimaHora24h,
    STDDEV(CAST(clima.temperaturaBulboSeco AS REAL)) as stddevTemperaturaBulboSeco24h,
    STDDEV(CAST(clima.temperaturaPontoOrvalho AS REAL)) as stddevTemperaturaPontoOrvalho24h,
    STDDEV(CAST(clima.temperaturaMaxUltimaHora AS REAL)) as stddevTemperaturaMaxUltimaHora24h,
    STDDEV(CAST(clima.temperaturaMinUltimaHora AS REAL)) as stddevTemperaturaMinUltimaHora24h,
    STDDEV(CAST(clima.temperaturaPontoOrvalhoMaxUltimaHora AS REAL)) as stddevTemperaturaPontoOrvalhoMaxUltimaHora24h,
    STDDEV(CAST(clima.temperaturaPontoOrvalhoMinUltimaHora AS REAL)) as stddevTemperaturaPontoOrvalhoMinUltimaHora24h,
    STDDEV(CAST(clima.umidadeRelativaMaxUltimaHora AS REAL)) as stddevUmidadeRelativaMaxUltimaHora24h,
    STDDEV(CAST(clima.umidadeRelativaMinUltimaHora AS REAL)) as stddevUmidadeRelativaMinUltimaHora24h,
    STDDEV(CAST(clima.umidadeRelativa AS REAL)) as stddevUmidadeRelativa24h,
    STDDEV(CAST(clima.ventoDirecaoGraus AS REAL)) as stddevVentoDirecaoGraus24h,
    STDDEV(CAST(clima.ventoRajadaMax AS REAL)) as stddevVentoRajadaMax24h,
    STDDEV(CAST(clima.ventoVelocidade AS REAL)) as stddevVentoVelocidade24h,

FROM database.slv_voos as voo

LEFT JOIN database.slv_clima as clima
    ON CAST(clima.data_hora_clima AS TIMESTAMP) >= (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 25 HOUR)
    AND CAST(clima.data_hora_clima AS TIMESTAMP) < (CAST(voo.data_hora_clima AS TIMESTAMP) - INTERVAL 1 HOUR)
WHERE voo.partidaReal IS NOT NULL
GROUP BY ALL